package main

import "strings"

// repo3Scenarios compare the v1 provider repositories (ComposerRepository
// providers-url / provider-includes / providers-lazy-url / list), the xz,
// rar and 7z archive paths of the downloaders (XzDownloader, RarDownloader,
// ZipDownloader) and the repository warnings (ResponseWarnings) of Composer
// f83588392df43d4fd027d84d26de459946ef4e80. The fixtures are generated by
// testdata/compare/vcs/repo3.sh (repo3-gen.php) and repo3stub.sh.
func init() {
	extraScenarios = append(extraScenarios, repo3Scenarios)
	extraOutputNormalizers = append(extraOutputNormalizers, normalizeVendorTempNames)
}

// normalizeVendorTempNames masks the random names ArchiveDownloader gives
// the archive (vendor/composer/tmp-<32 hex>) and its extraction directory
// (vendor/composer/<8 hex>) in extraction error messages, also when an
// exception box wrapped the name onto the next line. Only complete names of
// the expected length are masked.
func normalizeVendorTempNames(s string) string {
	const marker = "vendor/composer/"
	isHex := func(c byte) bool { return c >= '0' && c <= '9' || c >= 'a' && c <= 'f' }
	b := []byte(s)
	for i := 0; ; {
		j := strings.Index(string(b[i:]), marker)
		if j < 0 {
			break
		}
		pos := i + j + len(marker)
		want := 8
		if strings.HasPrefix(string(b[pos:]), "tmp-") {
			pos += 4
			want = 32
		}
		var idx []int
		k := pos
		for len(idx) < want {
			if k < len(b) && isHex(b[k]) {
				idx = append(idx, k)
				k++
				continue
			}
			// a wrapped exception box line: spaces, newline, indentation
			m := k
			for m < len(b) && b[m] == ' ' {
				m++
			}
			if len(idx) == 0 || m >= len(b) || b[m] != '\n' {
				break
			}
			m++
			for m < len(b) && b[m] == ' ' {
				m++
			}
			if m >= len(b) || !isHex(b[m]) {
				break
			}
			k = m
		}
		if len(idx) == want && (k >= len(b) || !isHex(b[k])) {
			for _, x := range idx {
				b[x] = 'x'
			}
		}
		i = pos
	}
	return string(b)
}

const repo3URL = "http://127.0.0.1:8899/git/repo3/"

// repo3Project is a project using only the given composer repositories.
func repo3Project(require string, extra string, repos ...string) string {
	var rs []string
	for _, r := range repos {
		if !strings.HasPrefix(r, "http") {
			r = repo3URL + r
		}
		rs = append(rs, `{"type": "composer", "url": "`+r+`"}`)
	}
	s := "{\n    \"name\": \"test/project\",\n    \"type\": \"project\",\n    \"repositories\": [\n        " + strings.Join(rs, ",\n        ") + ",\n        {\"packagist.org\": false}\n    ],\n    \"config\": {\"secure-http\": false},\n    \"autoload\": {\"psr-4\": {\"App\\\\\": \"src/\"}},\n    \"require\": " + require
	if extra != "" {
		s += ",\n    " + extra
	}
	return s + "\n}\n"
}

// archImage is the archive-tools variant of the selected oracle image
// (oracle/Containerfile.arch, built by scripts/prepare-oracle.sh).
func archImage() string { return oracleImage + "-arch" }

const archPath = "/opt/arch/bin:/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin"

func repo3Scenarios() []Scenario {
	files := map[string]string{"src/Kernel.php": appSrc}
	fx := []string{"repo3"}
	stubFx := []string{"repo3", "repo3stub"}
	cacheEnv := map[string]string{"COMPOSER_CACHE_DIR": "/work/out/cache"}
	type s struct {
		name, json, cmd string
		setup           []string
		env             map[string]string
		image           string
		probe           bool
		stub            bool
		snapshot        []string
		after           map[string]string
	}
	upd := "update --no-progress"
	list := []s{
		// --- v1 providers-url + provider-includes ---
		{name: "providers-update", json: repo3Project(`{"provfix/app": "*"}`, "", "prov"), cmd: upd, probe: true},
		{name: "providers-update-verbose", json: repo3Project(`{"provfix/app": "*"}`, "", "prov"), cmd: upd + " -v"},
		{name: "providers-install-lock", json: repo3Project(`{"provfix/app": "*"}`, "", "prov"), setup: []string{upd + " --no-install"}, cmd: "install --no-progress", probe: true},
		{name: "providers-update-cached", json: repo3Project(`{"provfix/lib": "^1.0"}`, "", "prov"), setup: []string{upd}, cmd: upd + " -v", env: cacheEnv},
		{name: "providers-root-listing", json: repo3Project(`{"provfix/lib": "^2.0", "provfix/tool": "*"}`, "", "provroot"), cmd: upd, probe: true},
		{name: "providers-dev-alias", json: repo3Project(`{"provfix/tool": "1.1.x-dev"}`, `"minimum-stability": "dev"`, "prov"), cmd: upd},
		{name: "providers-virtual", json: repo3Project(`{"provfix/tool-implementation": "^1.0"}`, "", "prov"), cmd: upd},
		{name: "providers-not-found", json: repo3Project(`{"provfix/nope": "^1.0"}`, "", "prov"), cmd: upd},
		{name: "providers-bad-hash", json: repo3Project(`{"provfix/lib": "^1.0"}`, "", "provbad"), cmd: upd},
		{name: "providers-bad-hash-other", json: repo3Project(`{"provfix/tool": "^1.0"}`, "", "provbad"), cmd: upd},
		{name: "providers-require", json: repo3Project(`{}`, "", "prov"), cmd: "require provfix/lib --no-progress"},
		{name: "providers-require-missing", json: repo3Project(`{}`, "", "prov"), cmd: "require provfix/missing --no-progress"},
		{name: "providers-show-available", json: repo3Project(`{}`, "", "prov"), cmd: "show -a provfix/lib"},
		{name: "providers-show-all", json: repo3Project(`{}`, "", "prov"), cmd: "show -a"},
		{name: "providers-show-all-names", json: repo3Project(`{}`, "", "prov"), cmd: "show -a -N"},
		{name: "providers-outdated", json: repo3Project(`{"provfix/lib": "1.0.0"}`, "", "prov"), setup: []string{upd}, cmd: "outdated --direct"},
		{name: "providers-update-one", json: repo3Project(`{"provfix/lib": "^1.0", "provfix/tool": "^1.0"}`, "", "prov"), setup: []string{upd}, cmd: "update provfix/lib --no-progress"},
		{name: "providers-depends", json: repo3Project(`{"provfix/app": "*"}`, "", "prov"), setup: []string{upd}, cmd: "depends provfix/lib"},
		{name: "providers-search", json: repo3Project(`{}`, "", "prov"), cmd: "search lib"},
		{name: "providers-search-name", json: repo3Project(`{}`, "", "prov"), cmd: "search --only-name tool"},
		{name: "providers-search-vendor", json: repo3Project(`{}`, "", "prov"), cmd: "search --only-vendor prov"},
		{name: "providers-search-list", json: repo3Project(`{}`, "", "provlist"), cmd: "search ^provfix/"},
		{name: "providers-search-list-other", json: repo3Project(`{}`, "", "provlist"), cmd: "search app"},
		// --- v1 providers-lazy-url ---
		{name: "providers-lazy-update", json: repo3Project(`{"provfix/app": "*"}`, "", "provlazy"), cmd: upd, probe: true},
		{name: "providers-lazy-not-found", json: repo3Project(`{"provfix/nope": "^1.0"}`, "", "provlazy"), cmd: upd},
		{name: "providers-lazy-show", json: repo3Project(`{}`, "", "provlazy"), cmd: "show -a provfix/tool"},
		{name: "providers-lazy-search", json: repo3Project(`{}`, "", "provlazy"), cmd: "search lib"},
		{name: "providers-lazy-cached", json: repo3Project(`{"provfix/lib": "^1.0"}`, "", "provlazy"), setup: []string{upd}, cmd: upd + " -v", env: cacheEnv},
		// --- xz / rar / 7z ---
		{name: "archive3-xz", json: repo3Project(`{"archfix/xzlib": "*"}`, "", "arch"), cmd: upd, probe: true},
		{name: "archive3-xz-status", json: repo3Project(`{"archfix/xzlib": "*"}`, "", "arch"), setup: []string{upd}, after: map[string]string{"vendor/archfix/xzlib/src/Xzlib.php": "<?php // changed\n"}, cmd: "status -v"},
		{name: "archive3-xz-reinstall", json: repo3Project(`{"archfix/xzlib": "*"}`, "", "arch"), setup: []string{upd}, cmd: "reinstall archfix/xzlib", probe: true},
		{name: "archive3-xz-remove", json: repo3Project(`{"archfix/xzlib": "*"}`, "", "arch"), setup: []string{upd}, cmd: "remove archfix/xzlib --no-progress"},
		{name: "archive3-rar-status", json: repo3Project(`{"archfix/rarlib": "*"}`, "", "arch"), setup: []string{upd}, after: map[string]string{"vendor/archfix/rarlib/composer.json": "{}\n"}, cmd: "status -v", image: "arch", env: map[string]string{"PATH": archPath}},
		{name: "archive3-xz-broken", json: repo3Project(`{"archfix/xzbroken": "*"}`, "", "arch"), cmd: upd},
		{name: "archive3-rar-no-unrar", json: repo3Project(`{"archfix/rarlib": "*"}`, "", "arch"), cmd: upd},
		{name: "archive3-rar", json: repo3Project(`{"archfix/rarlib": "*"}`, "", "arch"), cmd: upd, image: "arch", env: map[string]string{"PATH": archPath}, probe: true},
		{name: "archive3-rar-broken", json: repo3Project(`{"archfix/rarbroken": "*"}`, "", "arch"), cmd: upd, image: "arch", env: map[string]string{"PATH": archPath}},
		{name: "archive3-zip-7z", json: repo3Project(`{"archfix/ziplib": "*"}`, "", "arch"), cmd: upd, image: "arch", env: map[string]string{"PATH": archPath, "PHP_INI_SCAN_DIR": "/opt/arch/conf.d-nozip"}, probe: true},
		{name: "archive3-zip-7z-zipext", json: repo3Project(`{"archfix/ziplib": "*"}`, "", "arch"), cmd: upd, image: "arch", env: map[string]string{"PATH": archPath}, probe: true},
		{name: "archive3-zip-7z-crc", json: repo3Project(`{"archfix/zipcrc": "*"}`, "", "arch"), cmd: upd, image: "arch", env: map[string]string{"PATH": archPath, "PHP_INI_SCAN_DIR": "/opt/arch/conf.d-nozip"}},
		{name: "archive3-zip-7z-crc-zipext", json: repo3Project(`{"archfix/zipcrc": "*"}`, "", "arch"), cmd: upd, image: "arch", env: map[string]string{"PATH": archPath}},
		{name: "archive3-zip-no-command", json: repo3Project(`{"archfix/ziplib": "*"}`, "", "arch"), cmd: upd, image: "arch", env: map[string]string{"PHP_INI_SCAN_DIR": "/opt/arch/conf.d-nozip"}},
		{name: "archive3-zip-no-command-zipext", json: repo3Project(`{"archfix/ziplib": "*"}`, "", "arch"), cmd: upd, image: "arch", probe: true},
		{name: "archive3-zip-no-command-crc-zipext", json: repo3Project(`{"archfix/zipcrc": "*"}`, "", "arch"), cmd: upd, image: "arch"},
		// --- ResponseWarnings ---
		{name: "warnings-update", json: repo3Project(`{"provfix/app": "*"}`, "", "warn"), cmd: upd},
		{name: "warnings-update-ansi", json: repo3Project(`{"provfix/app": "*"}`, "", "warn"), cmd: upd + " --ansi"},
		{name: "warnings-show", json: repo3Project(`{}`, "", "warn"), cmd: "show -a provfix/lib"},
		{name: "warnings-search-api", json: repo3Project(`{}`, "", "warnsearch"), cmd: "search lib"},
		{name: "warnings-search-list", json: repo3Project(`{}`, "", "warnsearch"), cmd: "search ^provfix/"},
		{name: "warnings-show-names-list", json: repo3Project(`{}`, "", "warnsearch"), cmd: "show -a -N"},
		{name: "warnings-audit-api", json: repo3Project(`{"provfix/lib": "1.0.0"}`, "", "warnadv"), setup: []string{upd + " --no-audit --no-blocking"}, cmd: "audit"},
		{name: "warnings-update-audit-api", json: repo3Project(`{"provfix/lib": "1.0.0"}`, "", "warnadv"), cmd: upd + " --no-blocking"},
		{name: "warnings-filter-audit", json: repo3Project(`{"provfix/lib": "1.0.0"}`, "", "warnfilter"), setup: []string{upd + " --no-audit"}, cmd: "audit"},
		{name: "warnings-providers", json: repo3Project(`{"provfix/lib": "*"}`, "", "warnprov"), cmd: upd},
		{name: "warnings-two-repos", json: repo3Project(`{"provfix/app": "*"}`, "", "warn", "warnprov"), cmd: upd},
		{name: "warnings-http-403", json: repo3Project(`{"provfix/lib": "*"}`, "", "http://127.0.0.1:8900/w403"), cmd: upd, stub: true},
		{name: "warnings-http-404-metadata", json: repo3Project(`{"provfix/lib": "*"}`, "", "http://127.0.0.1:8900/w404"), cmd: upd, stub: true},
	}
	var out []Scenario
	for _, c := range list {
		sc := Scenario{Name: c.name, JSON: c.json, Files: files, Setup: c.setup, Command: c.cmd, Env: c.env, Probe: c.probe, GitFixtures: fx, Snapshot: c.snapshot, After: c.after}
		if c.stub {
			sc.GitFixtures = stubFx
		}
		if c.image == "arch" {
			sc.Image = archImage()
		}
		out = append(out, sc)
	}
	return out
}
